cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Test doubles implement the Source/Lease open, read and close interface.
function fixture({ values = ['a', 'b', null], read, close = async () => {}, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          return read ? read() : values.shift();
        },
        async close() {
          calls.closes++;
          await close();
        },
      };
    },
  };
  return { calls, stream: new EventService(source, mapper).stream() };
}

async function main() {
  // Construction and returning an unopened generator do not acquire a lease.
  {
    const { calls, stream } = fixture();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    assert.deepEqual(await stream.return(), { value: undefined, done: true });
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }

  // Each next reads exactly one record, including the exhaustion sentinel.
  {
    const mapped = [];
    const { calls, stream } = fixture({ mapper(value) { mapped.push(value); return value.toUpperCase(); } });
    for (const [index, value] of ['A', 'B'].entries()) {
      assert.deepEqual(await stream.next(), { value, done: false });
      await new Promise(resolve => setImmediate(resolve));
      assert.deepEqual(calls, { opens: 1, reads: index + 1, closes: 0 });
    }
    assert.deepEqual(mapped, ['a', 'b']);
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }

  for (const closeFails of [false, true]) {
    const closeError = new Error('close failed');
    const close = async () => { if (closeFails) throw closeError; };

    // Exhaustion, break and explicit return propagate cleanup failures.
    for (const exit of ['exhaustion', 'break', 'return']) {
      const { calls, stream } = fixture({ close });
      const consume = async () => {
        if (exit === 'return') {
          await stream.next();
          assert.deepEqual(await stream.return('returned'), { value: 'returned', done: true });
        } else {
          const found = [];
          for await (const value of stream) {
            found.push(value);
            if (exit === 'break') break;
          }
          assert.deepEqual(found, exit === 'break' ? ['A'] : ['A', 'B']);
        }
      };
      if (closeFails) await assert.rejects(consume(), error => error === closeError);
      else await consume();
      await stream.return();
      await stream.next();
      assert.deepEqual(calls, { opens: 1, reads: exit === 'exhaustion' ? 3 : 1, closes: 1 });
    }

    // Primary failures retain their identity, even for a thrown undefined.
    for (const failure of ['read', 'mapper', 'injected']) {
      for (const original of [new Error(`${failure} failed`), undefined]) {
        const { calls, stream } = fixture({
          close,
          read: failure === 'read' ? () => { throw original; } : undefined,
          mapper: failure === 'mapper' ? () => { throw original; } : undefined,
        });
        if (failure === 'injected') await stream.next();
        const result = failure === 'injected' ? stream.throw(original) : stream.next();
        await assert.rejects(result, error => error === original);
        await stream.next();
        await stream.return();
        assert.deepEqual(calls, { opens: 1, reads: 1, closes: 1 });
      }
    }
  }

  // Acquisition failure does not attempt to close a nonexistent lease.
  {
    const original = new Error('open failed');
    let opens = 0;
    const stream = new EventService({ open: async () => { opens++; throw original; } }).stream();
    assert.equal(opens, 0);
    await assert.rejects(stream.next(), error => error === original);
    await stream.return();
    assert.equal(opens, 1);
  }
}

module.exports = main();
module.exports.catch(error => {
  console.error(error);
  process.exitCode = 1;
});
